@_dataclass(slots=True)
class SummedHeader:
    kind: int = 0
    message_name: _ClassVar[str] = 'SummedHeader'
    min_wire_size: _ClassVar[int] = 1
    max_wire_size: _ClassVar[int] = 1
    wire_size: _ClassVar[int] = 1

    @staticmethod
    def read(r: gmsg.Reader) -> SummedHeader:
        m = SummedHeader()
        v0 = r.read('u8', 'little')
        m.kind = v0
        return m

    @staticmethod
    def write(w: gmsg.Writer, m: SummedHeader) -> None:
        w.write('u8', m.kind, 'little')

    @staticmethod
    def decode(data) -> SummedHeader:
        """Decode from bytes (trailing bytes are ignored). Raises gmsg.GmpError."""
        return SummedHeader.read(gmsg.Reader(data))

    @staticmethod
    def decode_with_extra(data) -> tuple[SummedHeader, int]:
        """Like decode(data): (message, extra), extra = bytes after the message (which decode ignores)."""
        r = gmsg.Reader(data)
        return SummedHeader.read(r), r.remaining

    def encode(self) -> bytes:
        w = gmsg.Writer()
        SummedHeader.write(w, self)
        return w.to_bytes()

    @staticmethod
    def view(data) -> SummedHeaderView:
        """A validated zero-copy view over encoded bytes."""
        return SummedHeaderView.from_bytes(data)

    def print_to(self, p: gmsg.Printer) -> None:
        p.begin('SummedHeader')
        p.key('kind')
        p.int_value(self.kind)
        p.end()

    def to_text(self, **options) -> str:
        return gmsg.to_text(self, **options)

    def __str__(self) -> str:
        return gmsg.to_text(self)


class SummedHeaderView:
    # Zero-copy view over an encoded SummedHeader; fields are read on access.
    __slots__ = ('_b', '_o', '_p', '_x')
    message_name = 'SummedHeader'
    min_wire_size = 1

    def __init__(self, b: memoryview, o: list[int] | None = None, p: list[bool] | None = None, x: int = 0) -> None:
        self._b, self._o, self._p, self._x = b, o, p, x

    @staticmethod
    def from_bytes(data) -> SummedHeaderView:
        """Validate data and build a view. Trailing bytes beyond the message are ignored. Raises gmsg.GmpError."""
        data = gmsg.as_view(data)
        if len(data) < 1: gmsg.fail(Err.TRUNCATED)
        return SummedHeaderView(data[:1], None, None, len(data) - 1)

    @staticmethod
    def unchecked(data) -> SummedHeaderView:
        """A view over data already validated by from_bytes() (no checks)."""
        data = gmsg.as_view(data)
        return SummedHeaderView(data[:1], None, None, len(data) - 1)

    @property
    def data(self) -> memoryview:
        """The message bytes."""
        return self._b

    @property
    def wire_size(self) -> int:
        return len(self._b)

    @property
    def extra_bytes(self) -> int:
        """Bytes after the message in the data given to from_bytes() (ignored; a protocol with exact_size rejects them)."""
        return self._x

    @property
    def kind(self) -> int:
        return gmsg.load(self._b, 0, 'u8', 'little')

    def ranges(self) -> list[gmsg.FieldRange]:
        """Byte ranges of the present fields (relative to data), in wire order; key is the attribute (None for
        padding and constants)."""
        out = []
        out.append(gmsg.FieldRange('kind', 'kind', 0, 1))
        return out

    def print_to(self, p: gmsg.Printer) -> None:
        p.begin('SummedHeader')
        x = self.kind
        p.key('kind')
        p.int_value(x)
        p.end()

    def to_text(self, **options) -> str:
        return gmsg.to_text(self, **options)

    def __str__(self) -> str:
        return gmsg.to_text(self)

    def __repr__(self) -> str:
        return '<SummedHeaderView ' + gmsg.to_text(self, style='single_line') + '>'

    def to_struct(self) -> SummedHeader:
        """Decode into the message dataclass."""
        return SummedHeader.decode(self._b)


